namespace RaceControl
{
    // The live page's HTML. Views for OBS browser sources: /?view=status|ftb|line|cone|order|log, &bare=1 drops the
    // page background; /board is the choose cone board itself (transparent around it).
    static class LivePage
    {
        public const string Html = @"<!doctype html>
<html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>
<title>RaceControl Live</title>
<link rel='icon' type='image/png' href='data:image/png;base64,'>
<style>
:root{--bg:#0d1117;--panel:#161b22;--line:#30363d;--text:#e6edf3;--dim:#8b949e;--green:#2ea043;--yellow:#e3b341;--red:#f85149;--blue:#58a6ff;--gold:#d29922}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.4 'Segoe UI',system-ui,sans-serif}
body.bare{background:transparent}
header{display:flex;flex-wrap:wrap;gap:12px;align-items:center;padding:12px 16px;border-bottom:1px solid var(--line)}
header h1{font-size:16px;margin:0 12px 0 0;letter-spacing:.5px}
.chip{padding:3px 10px;border-radius:12px;background:var(--panel);border:1px solid var(--line);font-weight:600}
.flag-green{background:var(--green);border-color:var(--green);color:#fff}.flag-yellow{background:var(--yellow);border-color:var(--yellow);color:#111}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px;padding:12px 16px}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:10px 12px;min-width:0}
body.bare .panel{background:rgba(13,17,23,.85)}
.panel h2{font-size:12px;text-transform:uppercase;letter-spacing:1px;color:var(--dim);margin:0 0 8px}
.cars{display:flex;flex-wrap:wrap;gap:4px}.car{min-width:34px;text-align:center;padding:2px 6px;border-radius:4px;background:#21262d;font-weight:700}
.car.w{background:var(--blue);color:#06101f}.car.l{opacity:.6}.car.p{outline:2px solid var(--gold)}
.row{display:flex;gap:8px;margin:3px 0;align-items:baseline}.row b{min-width:150px;color:var(--dim);font-weight:500}
table{width:100%;border-collapse:collapse}td,th{padding:3px 6px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}th{color:var(--dim);font-weight:500}
.lanes{display:grid;grid-template-columns:1fr 1fr;gap:8px}.lanes>div{min-width:0}.lanes div h3{margin:0 0 4px;font-size:12px;color:var(--dim)}
.log{font:12px/1.35 Consolas,monospace;white-space:pre-wrap;word-break:break-word;max-height:420px;overflow:auto}
.up{color:var(--green)}.down{color:var(--red)}.dim{color:var(--dim)}
.off{padding:40px;text-align:center;color:var(--dim)}
@media(max-width:600px){.row b{min-width:110px}}
</style></head><body>
<header id='hdr'><img src='data:image/png;base64,' alt='' width='32' height='32'><h1>RACECONTROL</h1><span class='chip' id='phase'>-</span><span class='chip' id='lap'></span><span class='chip' id='pits'></span><span class='dim' id='track'></span><span class='dim' id='upd'></span></header>
<div class='grid' id='grid'>
<section class='panel' data-v='ftb'><h2>First time by</h2><div id='ftb'></div></section>
<section class='panel' data-v='line'><h2>The line</h2><div id='line'></div></section>
<section class='panel' data-v='cone'><h2 id='coneT'>Choose cone</h2><div id='cone'></div></section>
<section class='panel' data-v='order'><h2>Running order</h2><div id='order'></div></section>
<section class='panel' data-v='log' style='grid-column:1/-1'><h2>Race Control log</h2><div class='log' id='log'></div></section>
</div>
<script>
var P=new URLSearchParams(location.search),view=P.get('view'),bare=P.get('bare')=='1';
if(bare)document.body.className='bare';
if(view){document.querySelectorAll('.panel').forEach(function(p){if(p.getAttribute('data-v')!=view)p.style.display='none';});if(view!='status'&&bare)document.getElementById('hdr').style.display='none';if(view=='status')document.getElementById('grid').style.display='none';}
function e(s){return String(s).replace(/[&<>]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;'}[c];});}
function cars(list,cls){if(!list||!list.length)return '<span class=dim>none</span>';return '<div class=cars>'+list.map(function(n){return '<span class=""car '+(cls&&cls(n)||'')+'"">'+n+'</span>';}).join('')+'</div>';}
var S={};
function wav(n){return S.w&&S.w[n]?'w':(S.l&&S.l[n]?'l':'');}
function draw(d){
 var ph=document.getElementById('phase');ph.textContent=d.inRace?d.phase:'Not in a race';ph.className='chip '+(d.inRace?(d.flag==7?'flag-green':'flag-yellow'):'');
 document.getElementById('lap').textContent=d.inRace?'Lap '+d.lap:'';
 document.getElementById('pits').textContent=d.inRace?'Pits: '+d.pits:'';
 document.getElementById('track').textContent=(d.track||'')+(d.preset?' - '+d.preset:'');
 document.getElementById('upd').textContent=d.time;
 var lg=document.getElementById('log');var atEnd=lg.scrollTop+lg.clientHeight>=lg.scrollHeight-20;lg.textContent=(d.log||[]).join('\n');if(atEnd)lg.scrollTop=lg.scrollHeight;
 if(!d.inRace){['ftb','line','cone','order'].forEach(function(i){document.getElementById(i).innerHTML='<div class=dim>waiting for a race</div>';});return;}
 S={w:{},l:{}};(d.order||[]).forEach(function(c){if(c.waved)S.w[c.num]=1;if(c.down>=1)S.l[c.num]=1;});
 var f=d.firstTimeBy;
 document.getElementById('ftb').innerHTML=!d.caution?'<div class=dim>green flag</div>':
  '<div class=row><b>Waved around</b>'+cars(f.waved,function(){return 'w';})+'</div>'+
  '<div class=row><b>Lead lap, sent around</b>'+cars(f.around)+'</div>'+
  '<div class=row><b>Pitted</b>'+cars(f.pitted)+'</div>'+
  '<div class=row><b>Stayed out, lead lap</b>'+cars(f.lead)+'</div>'+
  '<div class=row><b>Lapped, behind the leader</b>'+cars(f.behind)+'</div>'+
  '<div class=row><b>Under penalty</b>'+cars(f.penalty)+'</div>';
 var L=d.line,h='';
 if(!d.caution||!L.active)h='<div class=dim>'+(d.caution?'not lined up yet':'green flag')+'</div>';
 else if(L.inside.length||L.outside.length)h=(L.coneWaiting?'<div class=dim>cone waits for lapped cars to drop back</div>':'')+'<div class=lanes><div><h3>INSIDE</h3>'+cars(L.inside,wav)+'</div><div><h3>OUTSIDE</h3>'+cars(L.outside,wav)+'</div></div>';
 else h=(L.coneWaiting?'<div class=dim>cone waits for lapped cars to drop back</div>':'')+'<h3 class=dim style=""font-size:12px;margin:0 0 4px"">SINGLE FILE</h3>'+cars(L.single,wav);
 document.getElementById('line').innerHTML=h;
 var c=d.cone;
 if(!c){document.getElementById('cone').innerHTML='<div class=dim>no cone yet</div>';}
 else{document.getElementById('coneT').textContent=c.title+(c.done?'':' - choosing');
  var n=Math.max(c.inside.length,c.outside.length),t='<table><tr><th>Row</th><th>Inside</th><th></th><th>Outside</th><th></th></tr>';
  function g(x){if(!x)return '<td></td><td></td>';var s=x.gained>0?'<span class=up>&#9650;'+x.gained+'</span>':x.gained<0?'<span class=down>&#9660;'+(-x.gained)+'</span>':'<span class=dim>-</span>';return '<td><b>#'+x.num+'</b></td><td>'+s+'</td>';}
  for(var r=0;r<n;r++)t+='<tr><td class=dim>'+(r+1)+'</td>'+g(c.inside[r])+g(c.outside[r])+'</tr>';
  document.getElementById('cone').innerHTML=t+'</table>';}
 var o='<table><tr><th>Pos</th><th>Car</th><th>Laps down</th><th></th></tr>';
 (d.order||[]).forEach(function(x){var tags=[];if(x.pit)tags.push('pit road');if(x.waved)tags.push('<span style=""color:var(--blue)"">waved</span>');if(x.penalty)tags.push('<span class=down>penalty</span>');if(x.player)tags.push('<span style=""color:var(--gold)"">you</span>');
  o+='<tr><td class=dim>'+x.pos+'</td><td><b>#'+x.num+'</b></td><td>'+(x.down>0?x.down:'<span class=dim>lead lap</span>')+'</td><td>'+tags.join(', ')+'</td></tr>';});
 document.getElementById('order').innerHTML=o+'</table>';
}
function tick(){fetch('state.json',{cache:'no-store'}).then(function(r){return r.json();}).then(draw).catch(function(){document.getElementById('upd').textContent='Race Control not answering';}).finally(function(){setTimeout(tick,1000);});}
tick();
</script></body></html>";

        public const string BoardHtml = @"<!doctype html>
<html><head><meta charset='utf-8'><title>Choose cone board</title>
<style>html,body{margin:0;background:transparent;overflow:hidden}img{display:block;max-width:100vw;max-height:100vh}</style></head>
<body><img id='b' alt=''>
<script>
var img=document.getElementById('b'),next=new Image();
function load(){next=new Image();next.onload=function(){img.src=next.src;setTimeout(load,66);};next.onerror=function(){setTimeout(load,1000);};next.src='board.png?t='+Date.now();}
load();
</script></body></html>";
    }
}
